import pandas as pd
import numpy as np
import json

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

# Read the PVC sheet
df = pd.read_excel(DATA_FILE, sheet_name="PVC")

# Identify columns based on preview info
temp_col = "Temperature (°C)"
weight_col = "Weight (%)"
dtg_col = "Deriv. Weight (%/°C)"

# Filter data for 200-400 C range to calculate mass loss
mask_200_400 = (df[temp_col] >= 200) & (df[temp_col] <= 400)
df_range = df[mask_200_400].copy()

if not df_range.empty:
    # Find weight at 200°C and 400°C using nearest point interpolation logic or direct lookup
    # Since TGA data is discrete, we find the points closest to 200 and 400

    # Get index of point closest to 200
    idx_200 = (df_range[temp_col] - 200).abs().idxmin()
    w_200 = float(df.loc[idx_200, weight_col])

    # Get index of point closest to 400
    idx_400 = (df_range[temp_col] - 400).abs().idxmin()
    w_400 = float(df.loc[idx_400, weight_col])

    mass_loss = w_200 - w_400
else:
    mass_loss = 0.0
    w_200 = 100.0
    w_400 = 100.0

# Prepare full data for plotting
temps = [float(t) for t in df[temp_col]]
weights = [float(w) for w in df[weight_col]]
dtgs = [-float(d) for d in df[dtg_col]] # Multiply by -1 so peaks point up

# Calculate Residue (nearest to 800 C)
idx_res = (df[temp_col] - 800).abs().idxmin()
residue_val = float(df.loc[idx_res, weight_col])
residue_temp = float(df.loc[idx_res, temp_col])

# Calculate Peak (highest DTG peak above 150 C)
# dtgs are already negated, so highest value is the deepest original dip
mask_peak = df[temp_col] > 150
df_peak_candidates = df[mask_peak]
if not df_peak_candidates.empty:
    # Find max of negated DTG in this range
    # We want the highest peak in the plot (which corresponds to most negative original DTG).
    # So we look for max of the negated series.
    idx_peak = df_peak_candidates[dtg_col].idxmin() # Most negative original = Highest plotted peak
    peak_temp = float(df.loc[idx_peak, temp_col])
    peak_weight = float(df.loc[idx_peak, weight_col])
else:
    peak_temp = 0.0
    peak_weight = 0.0

